export default async function ticket({ page, previous }, ctx) {
  if (
    !Array.isArray(page?.tickets) ||
    typeof page.after_cursor !== "string" ||
    typeof page.end_of_stream !== "boolean"
  )
    throw Error("Invalid ticket page");
  const s = await ctx.state.get("zendesk-notes-cursor"),
    pageKey = s.cursor ?? String(s.startTime);
  let i = previous?.pageKey === pageKey ? previous.index : 0;
  while (i < page.tickets.length) {
    const t = page.tickets[i++];
    if (!Number.isSafeInteger(t.id)) throw Error("Invalid ticket");
    if (t.via?.channel !== "email") continue;
    const email = t.via?.source?.from?.address;
    if (typeof email !== "string" || !email) throw Error("Email channel missing sender address");
    return { state: { index: i, pageKey }, more: true, fetchNext: false, ticketId: t.id, email };
  }
  if (!page.end_of_stream && page.after_cursor === s.cursor) throw Error("Repeated ticket cursor");
  s.cursor = page.after_cursor;
  await ctx.state.set("zendesk-notes-cursor", s);
  return {
    state: { index: i, pageKey },
    more: false,
    fetchNext: !page.end_of_stream,
    ticketId: 1,
    email: "none@example.invalid",
  };
}

