export default function person({ items, nextCursor, email }) {
  if (nextCursor || items.length > 1) throw Error("Ambiguous Pipedrive contact");
  if (!items.length) return { found: false, personId: 1 };
  const p = items[0].item;
  if (
    !p?.emails?.some((x) => x.toLowerCase() === email.toLowerCase()) ||
    !Number.isSafeInteger(p.id)
  )
    throw Error("Invalid contact match");
  return { found: true, personId: p.id };
}

