export default function f({ ticketId, previous }) {
  const q = { "page[size]": 100 };
  if (previous?.ticketId === ticketId && previous.cursor) q["page[after]"] = previous.cursor;
  return { endpoint: "/api/v2/tickets/" + ticketId + "/comments.json", query: q };
}

