export default async function comments(
  { page, previous, ticketId, personId, since, acknowledge, resolution },
  ctx,
) {
  if (!Array.isArray(page?.comments) || typeof page.meta?.has_more !== "boolean")
    throw Error("Invalid comment page");
  const cursor = previous?.ticketId === ticketId ? previous.cursor : null;
  let i = previous?.ticketId === ticketId && previous.pageCursor === cursor ? previous.index : 0;
  while (i < page.comments.length) {
    const c = page.comments[i++];
    if (
      !Number.isSafeInteger(c.id) ||
      !Number.isFinite(Date.parse(c.created_at)) ||
      typeof c.body !== "string"
    )
      throw Error("Invalid comment");
    if (Date.parse(c.created_at) < since * 1000) continue;
    const key = "zendesk-note:" + ticketId + ":" + c.id,
      old = await ctx.state.get(key);
    if (old?.status === "done") continue;
    if (old?.status === "pending") {
      if (acknowledge !== key || !["absent", "confirmed"].includes(resolution))
        throw Error("Inspect pending Pipedrive note " + key);
      if (resolution === "confirmed") {
        await ctx.state.set(key, { status: "done" });
        continue;
      }
    }
    await ctx.state.set(key, { status: "pending" });
    const esc = (x) =>
      String(x)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    return {
      state: { ticketId, cursor, pageCursor: cursor, index: i },
      more: true,
      fetchNext: false,
      query: {},
      key,
      body: {
        person_id: personId,
        content:
          "Message imported from Zendesk<br>From " +
          esc(c.via?.source?.from?.name ?? "Zendesk user") +
          "<br>" +
          esc(c.body).replaceAll("\n", "<br>"),
      },
    };
  }
  if (page.meta.has_more) {
    const after = page.meta.after_cursor;
    if (typeof after !== "string" || !after || after === cursor)
      throw Error("Invalid comment cursor");
    return {
      state: { ticketId, cursor: after, pageCursor: cursor, index: i },
      more: false,
      fetchNext: true,
      query: { "page[size]": 100, "page[after]": after },
      key: "",
      body: {},
    };
  }
  return {
    state: { ticketId, cursor: null, pageCursor: cursor, index: i },
    more: false,
    fetchNext: false,
    query: {},
    key: "",
    body: {},
  };
}

